// A photo the site shows from the school's own media (wave 2). The Home manifest
// (apps/web/src/content/media.ts) is generated by tools/media/build-media.mjs and checked against
// this schema by tools/media/check-media.test.mjs.
//
// Consent (owner decision 2026-11-06): students appear only in non-identifiable shots (hands,
// backs, distant, objects); adults (staff, guests, parents) may be recognisable. "authorized" is
// for a later photo with written parental authorization on file.
import { z } from "zod";
import { locales } from "./locales";

export const photoConsents = ["non-identifiable", "adults", "authorized"] as const;
export type PhotoConsent = (typeof photoConsents)[number];

const altText = z.object(Object.fromEntries(locales.map((l) => [l, z.string().trim().min(8).max(200)])) as Record<(typeof locales)[number], z.ZodString>);

export const photoSchema = z.object({
  id: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  event: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  /** Day the photo was taken (camera clock or file name), or null. */
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).nullable(),
  consent: z.enum(photoConsents),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
  /** Widths of the files served, /media/photos/<id>-<width>.(avif|webp), smallest first. */
  widths: z.array(z.number().int().positive()).min(1),
  /** Where the subject is, [x, y] as fractions, for object-position when the photo is cropped. */
  focus: z.tuple([z.number().min(0).max(1), z.number().min(0).max(1)]),
  blur: z.string().startsWith("data:image/"),
  alt: altText,
});
export type Photo = z.infer<typeof photoSchema>;
